+        mv(MoveKind::Feed, Point3::new(0.0, 0.0, 15.0), Point3::new(0.0, 0.0, 30.0)),
+    ];
+    if let Err(e) = s.simulate(&[SimOp { moves: &moves, radius: 3.0, ball: false, cone: None, corner: None }]) {
+        panic!("simulate: {e:?}");
+    }
+    s
+}
